from fractions import Fraction
from itertools import product

def bayes_cond(f, n, p, q, prefix):
    """E_Q[f | F_k] at the node `prefix` (k = len(prefix)) of an n-toss tree.
    Return a pair of exact Fractions: (directly under Q, by E_P[Z_n f | F_k] / Z_k).
    f takes the full path string; p and q are the up chances under P and Q."""
    p, q = Fraction(p), Fraction(q)
    def chance(path, a):
        return a ** path.count('H') * (1 - a) ** path.count('T')
    def weight(path):
        return chance(path, q) / chance(path, p)
    tails = [''.join(w) for w in product('HT', repeat=n - len(prefix))]
    direct = sum((chance(t, q) * f(prefix + t) for t in tails), Fraction(0))
    numer = sum((chance(t, p) * weight(prefix + t) * f(prefix + t) for t in tails), Fraction(0))
    return direct, numer / weight(prefix)
